    }

    function download(state, rows) {
      return calendarFile(plan, preview(state, rows), state.weekStart, metadata,
        (item) => state.weekStart.replace(/-/g, "") + "-" + item.key);
    }
    return Object.freeze({ preview, download, source: metadata.source, totalCount: plan.items.length });
  }

  function mount(element) {
    const week = element.querySelector("#calendarWeek");
    const button = element.querySelector("#calendarDownload");
    const list = element.querySelector("#calendarPreview");
    const status = element.querySelector("#calendarStatus");
    const source = element.querySelector("#calendarSource");
    let session = null;

    function clear() {
      session = null;
      button.disabled = true;
      list.replaceChildren();
      source.textContent = "";
      status.textContent = "";
      element.hidden = true;
    }

    function refresh() {
      button.disabled = true;
      list.replaceChildren();
      if (!session) return;
      if (!session.count) {
        status.textContent = "There are no checked suggestions to export. Unavailable days stay open.";
        return;
      }
      try {
        const items = session.preview(week.value);
        for (const item of items) {
          const row = element.ownerDocument.createElement("li");
          row.textContent = item.day + " " + item.date + " — " + item.name + " (all-day suggestion)";
          list.append(row);
        }
        status.textContent = items.length + " suggested events for the week beginning " + week.value + ". Days without a suggestion stay open.";
        button.disabled = false;
      } catch (error) {
        status.textContent = error.message;
      }
    }

    week.addEventListener("input", refresh);
    week.addEventListener("change", refresh);
    button.addEventListener("click", () => {
      if (!session) return;
      let url;
      try {
        const output = session.download(week.value);
        url = URL.createObjectURL(new Blob([output.text], { type: "text/calendar;charset=utf-8" }));
        const link = element.ownerDocument.createElement("a");
        link.href = url;
        link.download = output.filename;
        element.ownerDocument.body.append(link);
        link.click();
        link.remove();
        status.textContent = "Calendar file prepared. Open it in your calendar app to review and import the suggestions.";
      } catch (error) {
        status.textContent = "Calendar download unavailable: " + error.message;
      } finally {
        if (url) setTimeout(() => URL.revokeObjectURL(url), 1000);
      }
    });

    return Object.freeze({
      clear,
      setResult(result) {
        clear();
        element.hidden = false;
        try {
          session = createPlanExport(result);
          source.textContent = session.source;
          refresh();
        } catch (error) {
          status.textContent = "Calendar download unavailable: " + error.message;
        }
      },
    });
  }

  return Object.freeze({ createPlanExport, createWeekExport, mount });
});

/** Local scheduling of an existing checked plan. No recommendation or provider calls. */
export const DAYS = Object.freeze([
  "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday",
]);

function freeze(value) {
  if (value && typeof value === "object" && !Object.isFrozen(value)) {
    Object.values(value).forEach(freeze);
    Object.freeze(value);
  }
  return value;
}

function dateKey(date) {
  const year = date.getUTCFullYear();
  if (year < 1 || year > 9999) throw new RangeError("Choose a week within years 0001–9999.");
  return date.toISOString().slice(0, 10);
}

function parseDate(value) {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    throw new RangeError("Choose a valid calendar date for your week.");
  }
  const date = new Date(`${value}T12:00:00.000Z`);
  if (!Number.isFinite(date.getTime()) || dateKey(date) !== value) {
    throw new RangeError("Choose a valid calendar date for your week.");
  }
  return date;
}

/** Calendar dates use UTC arithmetic so a daylight-saving change cannot skip a day. */
export function calendarWeek(anchor) {
  const date = parseDate(anchor);
  date.setUTCDate(date.getUTCDate() - (date.getUTCDay() + 6) % 7);
  return DAYS.map((day) => {
    const row = Object.freeze({ day, date: dateKey(date) });
    date.setUTCDate(date.getUTCDate() + 1);
    return row;
  });
}

/** Use the browser's current calendar date, not the UTC date near local midnight. */
export function localDate(now = new Date()) {
  if (!(now instanceof Date) || !Number.isFinite(now.getTime())) {
    throw new RangeError("A valid current date is required.");
  }
  return `${String(now.getFullYear()).padStart(4, "0")}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
}

export function createWeekPlan(response, anchor = localDate()) {
  if (!response?.plan || !Array.isArray(response.plan.meals)) {
    throw new TypeError("The response does not contain a weekly plan.");
  }
  const sourcePlan = structuredClone(response.plan);
  const picks = [...sourcePlan.meals, ...(sourcePlan.outing ? [sourcePlan.outing] : [])]
    .map((pick, index) => {
      if (!pick || !DAYS.includes(pick.day) || !["restaurant", "outing"].includes(pick.kind)
          || typeof pick.entity_id !== "string" || !pick.entity_id.trim()) {
        throw new TypeError("A suggested pick is missing its source identity, kind or day.");
      }
      return { key: `pick-${index}`, originalDay: pick.day, pick };
    });
  return freeze({
    weekStart: calendarWeek(anchor)[0].date,
    sourceMode: response.mock === true ? "mock" : response.mock === false ? "live" : "unknown",
    constraints: structuredClone(response.comparison?.constraints ?? []),
    sourcePlan,
    picks,
    assignments: Object.fromEntries(picks.map(({ key, originalDay }) => [key, originalDay])),
  });
}

export function setWeek(state, anchor) {
  return freeze({ ...state, weekStart: calendarWeek(anchor)[0].date });
}

/** Multiple checked picks may share a day; no pick is duplicated or displaced. */
export function setPickDay(state, key, day) {
  if (!state.picks.some((pick) => pick.key === key)) throw new RangeError("Unknown suggested pick.");
  if (day !== null && !DAYS.includes(day)) throw new RangeError("Choose a weekday or leave this pick off the week.");
  return freeze({ ...state, assignments: { ...state.assignments, [key]: day } });
}

export function resetDays(state) {
  return freeze({
    ...state,
    assignments: Object.fromEntries(state.picks.map(({ key, originalDay }) => [key, originalDay])),
  });
}

export function weekRows(state) {
  return calendarWeek(state.weekStart).map((row) => ({
    ...row, picks: state.picks.filter(({ key }) => state.assignments[key] === row.day),
  }));
}

export function offWeekPicks(state) {
  return state.picks.filter(({ key }) => state.assignments[key] === null);
}

/** Portable, user-opened snapshots of an existing TasteTable week. */
import { createWeekPlan, setPickDay } from "./week_plan.mjs";

export const WEEK_FILE_FORMAT = "tastetable.saved-week.v1";

const object = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
const copy = (value) => structuredClone(value);
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

function requireValue(condition, message) {
  if (!condition) throw new TypeError(message);
}

function timestamp(value) {
  requireValue(typeof value === "string", "The saved week is missing a valid timestamp.");
  const date = new Date(value);
  requireValue(Number.isFinite(date.getTime()) && date.toISOString() === value,
    "The saved week is missing a valid timestamp.");
  return value;
}

function readInputs(value) {
  requireValue(object(value), "The saved week is missing its original inputs.");
  for (const key of ["cuisines", "music", "films", "constraints"]) {
    requireValue(Array.isArray(value[key]) && value[key].every((item) => typeof item === "string"),
      "The saved week has invalid " + key + " inputs.");
  }
  requireValue(typeof value.city === "string", "The saved week has an invalid city input.");
  return copy(value);
}

function textFields(value, fields, label) {
  requireValue(object(value) && fields.every((field) => typeof value[field] === "string"),
    "The saved response has invalid " + label + ".");
}

function readResponse(value) {
  requireValue(object(value) && object(value.plan), "The saved week is missing its original response.");
  const plan = value.plan;
  requireValue(Array.isArray(plan.meals) && Array.isArray(plan.notes)
    && plan.notes.every((note) => typeof note === "string") && Array.isArray(plan.rejected),
  "The saved response has an incomplete original plan.");
  for (const pick of [...plan.meals, ...(plan.outing == null ? [] : [plan.outing])]) {
    textFields(pick, ["name", "why", "entity_id", "kind", "day"], "original pick fields");
    requireValue(pick.affinity == null || (typeof pick.affinity === "number" && Number.isFinite(pick.affinity)),
      "The saved response has an invalid affinity value.");
    requireValue(pick.fallback === undefined || typeof pick.fallback === "boolean",
      "The saved response has an invalid fallback value.");
  }
  requireValue(object(value.llm_only) && Array.isArray(value.llm_only.meals),
    "The saved response is missing its original comparison plan.");
  for (const pick of [...value.llm_only.meals, value.llm_only.outing]) {
    textFields(pick, ["name", "why", "day"], "comparison pick fields");
  }
  // These fields are native numeric counts, including two inherited raw HTML
  // interpolation sites. A local file must not supply HTML in their place.
  const counts = ["picks", "with_qloo_entity_id", "with_affinity_evidence", "constraint_checked", "unsafe_candidates_rejected"];
  for (const side of ["grounded", "llm_only"]) {
    const values = value.comparison?.[side];
    requireValue(object(values) && counts.every((key) => Number.isSafeInteger(values[key]) && values[key] >= 0),
      "The saved response has invalid comparison counts.");
  }
  for (const rejected of plan.rejected) {
    textFields(rejected, ["name"], "rejected candidate fields");
    requireValue(Array.isArray(rejected.failed), "The saved response has invalid rejected checks.");
    for (const check of rejected.failed) textFields(check, ["constraint", "status", "reason"], "rejected check fields");
  }
  requireValue(Array.isArray(value.trace), "The saved response is missing its original tool trace.");
  for (const entry of value.trace) {
    textFields(entry, ["tool", "result_summary"], "tool trace fields");
    // Native decoder recovery deliberately retains null, arrays and scalar
    // arguments in diagnostics. JSON.stringify + escaping renders them as data.
    requireValue(Object.hasOwn(entry, "args"), "The saved response is missing tool arguments.");
  }
  return copy(value);
}

function restore(value) {
  requireValue(object(value) && value.format === WEEK_FILE_FORMAT,
    "Choose a TasteTable saved-week file in the supported v1 format.");
  const receivedAt = timestamp(value.receivedAt);
  const savedAt = timestamp(value.savedAt);
  requireValue(value.calendarId === null || (typeof value.calendarId === "string" && /^[0-9a-f]{32}$/.test(value.calendarId)),
    "The saved week has an invalid calendar identity.");
  const inputs = readInputs(value.inputs);
  requireValue(object(value.week) && object(value.week.assignments),
    "The saved week is missing its arrangement.");
  const response = readResponse(value.response);
  let state = createWeekPlan(response, value.week.start);
  requireValue(state.weekStart === value.week.start,
    "The saved week must identify the Monday of its displayed week.");
  requireValue(same(inputs.constraints, state.constraints),
    "The saved inputs and the original response have different constraints.");
  const keys = state.picks.map(({ key }) => key);
  requireValue(Object.keys(value.week.assignments).length === keys.length
    && keys.every((key) => Object.hasOwn(value.week.assignments, key)),
  "The saved arrangement must include every original pick exactly once.");
  for (const key of keys) state = setPickDay(state, key, value.week.assignments[key]);
  return { response, inputs, state, receivedAt, savedAt, calendarId: value.calendarId };
}

/** The response is retained whole, including source explanations and tool trace. */
export function makeWeekFile({ response, inputs, state, receivedAt, calendarId }, now = new Date()) {
  const envelope = {
    format: WEEK_FILE_FORMAT,
    receivedAt,
    savedAt: now.toISOString(),
    calendarId,
    inputs: copy(inputs),
    response: copy(response),
    week: { start: state?.weekStart, assignments: copy(state?.assignments) },
  };
  const restored = restore(envelope);
  requireValue(same(state, restored.state),
    "The arranged week no longer matches its original response.");
  return {
    filename: `tastetable-week-${state.weekStart}.json`,
    text: JSON.stringify(envelope, null, 2) + "\n",
  };
}

/** Recreate native immutable state; serialized derived picks are never trusted. */
export function readWeekFile(text) {
  requireValue(typeof text === "string", "The saved week must be a JSON text file.");
  let value;
  try {
    // A UTF-8 BOM is accepted for ordinary editor/file interoperability.
    value = JSON.parse(text.replace(/^\uFEFF/, ""));
  } catch {
    throw new TypeError("This file is not valid JSON. Choose a saved TasteTable week.");
  }
  return restore(value);
}

/** A caregiver's visit notes. No venue contact, recommendation or storage calls. */
import { calendarWeek, setWeek, weekRows } from "./week_plan.mjs";
import { mountVenueNoteFiles } from "./venue_note_file.mjs";

export const CONTACT_STATES = Object.freeze({
  not_contacted: "Not contacted",
  awaiting_reply: "Awaiting reply",
  reply_recorded: "Reply recorded",
  follow_up: "Needs follow-up",
});

const EMPTY_NOTE = Object.freeze({ status: "not_contacted", question: null, reply: "", replyQuestions: null, nextStep: "" });
const QUESTIONS = Object.freeze({
  soft_foods: "Which soft-food options could you prepare? Confirm the required texture with the care team.",
  low_sodium: "Can the kitchen prepare a lower-salt option, and how would it be prepared?",
  wheelchair: "Is there step-free access to the entrance, seating and facilities needed for this visit?",
});
const SOURCES = Object.freeze({
  mock: "Demo plan: fictional venues and synthetic source data. Use this sheet to practise the workflow.",
  live: "Plan returned by Qloo. Venue details and availability still need confirmation.",
  unknown: "The response did not specify its data source. Establish the venue's identity before using this plan.",
});
const NOTE_LIMITS = Object.freeze({ question: 2000, reply: 2000, nextStep: 500 });
const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const indent = (value) => String(value).split(/\r?\n/).map((line) => `  ${line}`).join("\n");

/** Bind notes to the accepted source, pick occurrence and exact scheduled date. */
export function createVenueFollowup(initial, savedSource = "") {
  if (typeof savedSource !== "string") throw new TypeError("The saved-source label must be text.");
  const source = initial.sourcePlan;
  const picks = initial.picks;
  const constraints = initial.constraints;
  const sourceMode = initial.sourceMode;
  const sourceLabel = [SOURCES[sourceMode], savedSource].filter(Boolean).join("\n");
  let records = new Map();

  function suggestedQuestions(pick, date) {
    return [
      `Will you be open on ${date}, and do we need to book?`,
      ...constraints.filter((constraint) => QUESTIONS[constraint]
        && (pick.kind === "restaurant" || constraint === "wheelchair")).map((constraint) => QUESTIONS[constraint]),
    ];
  }

  function entries(state) {
    if (state?.sourcePlan !== source || state.picks !== picks || state.constraints !== constraints || state.sourceMode !== sourceMode) {
      throw new Error("This worksheet belongs to a different accepted plan.");
    }
    return weekRows(state).flatMap(({ day, date, picks: scheduled }) => scheduled.map(({ key, pick }) => {
      const questionsForVisit = suggestedQuestions(pick, date);
      const note = records.get(JSON.stringify([key, date])) || EMPTY_NOTE;
      const questionText = note.question ?? questionsForVisit.join("\n");
      return {
        key, day, date, pick, occurrence: picks.findIndex((item) => item.key === key) + 1,
        questionText, questions: questionText.split(/\r?\n/).filter((line) => line.trim()), note,
        questionsChangedAfterReply: Boolean(note.reply.trim() && note.replyQuestions !== questionText),
      };
    }));
  }

  function setField(state, key, date, field, value) {
    const entry = entries(state).find((item) => item.key === key && item.date === date);
    if (!entry) throw new Error("That visit is no longer scheduled on this date.");
    if (typeof value !== "string") throw new TypeError("Enter a text value for the venue note.");
    if (field === "status") {
      if (!Object.hasOwn(CONTACT_STATES, value)) throw new RangeError("Choose a listed contact status.");
      if (value === "reply_recorded" && entry.questionsChangedAfterReply) {
        throw new Error("Update the reply for the revised questions before marking a reply recorded.");
      }
    } else if (!Object.hasOwn(NOTE_LIMITS, field) || value.length > NOTE_LIMITS[field]) {
      throw new RangeError("The venue note field is unknown or too long.");
    }
    const updated = { ...entry.note, [field]: value };
    if (field === "reply") updated.replyQuestions = value.trim() ? entry.questionText : null;
    if (field === "question" && value !== entry.questionText && updated.reply.trim() && updated.replyQuestions !== value) {
      updated.status = "follow_up";
    }
    const note = Object.freeze(updated);
    records.set(JSON.stringify([key, date]), note);
    return note;
  }

  function text(state) {
    const visits = entries(state);
    if (!visits.length) throw new Error("Schedule at least one pick to prepare a call sheet.");
    const lines = [
      "TasteTable — venue call sheet", `Week beginning ${state.weekStart}`, sourceLabel,
      "Caregiver-entered notes. A recorded reply is not a safety check, reservation or confirmation by TasteTable.",
      "Confirm venue details and care needs before going. Do not include names or private health information.",
      "Notes apply to the pick occurrence and date shown. Later edits do not update this copy.", "",
    ];
    for (const entry of visits) {
      lines.push(`${entry.day} ${entry.date} — ${entry.pick.name}`,
        `Suggested visit ${entry.occurrence}; Qloo entity: ${entry.pick.entity_id}`,
        "Original plan explanation (heuristic):", indent(entry.pick.why), "Questions to ask:",
        ...(entry.questions.length ? entry.questions.map((question) => `  • ${question}`) : ["  No questions entered."]),
        `Caregiver contact status: ${CONTACT_STATES[entry.note.status]}`,
        ...(entry.questionsChangedAfterReply ? [
          "Questions changed after these notes were entered. Follow up on the revised questions.",
          "Questions for the earlier reply / notes:", indent(entry.note.replyQuestions),
          "Earlier reply / notes (for the previous questions):",
        ] : ["Venue reply / your notes:"]), indent(entry.note.reply || "No reply details entered."),
        "Next step:", indent(entry.note.nextStep || "No next step recorded."), "");
    }
    return lines.join("\n");
  }


  /** Copy every retained occurrence/date record, including visits currently omitted. */
  function snapshotRecords() {
    return Object.freeze([...records].map(([identity, note]) => {
      const [key, date] = JSON.parse(identity);
      return Object.freeze({ key, date, note: Object.freeze({ ...note }) });
    }));
  }

  /** Validate a complete replacement without changing any live note. */
  function prepareRecords(rows) {
    if (!Array.isArray(rows)) throw new TypeError("The notes file must contain a list of visit records.");
    const seen = new Set();
    const fields = ["status", "question", "reply", "replyQuestions", "nextStep"];
    const exact = (value, names) => value !== null && typeof value === "object" && !Array.isArray(value)
      && Object.keys(value).length === names.length && names.every((name) => Object.hasOwn(value, name));
    return Object.freeze(rows.map((row) => {
      if (!exact(row, ["key", "date", "note"])) throw new TypeError("A venue record has unsupported fields.");
      const item = picks.find(({ key }) => key === row.key);
      if (!item || typeof row.date !== "string" || !calendarWeek(row.date).some(({ date }) => date === row.date)) {
        throw new TypeError("A venue record has an unknown pick or invalid date.");
      }
      const identity = JSON.stringify([row.key, row.date]);
      if (seen.has(identity)) throw new TypeError("The notes file repeats a pick and date.");
      seen.add(identity);
      const note = row.note;
      if (!exact(note, fields) || typeof note.status !== "string" || !Object.hasOwn(CONTACT_STATES, note.status)
          || (note.question !== null && (typeof note.question !== "string" || note.question.length > NOTE_LIMITS.question))
          || typeof note.reply !== "string" || note.reply.length > NOTE_LIMITS.reply
          || typeof note.nextStep !== "string" || note.nextStep.length > NOTE_LIMITS.nextStep
          || (note.replyQuestions !== null && (typeof note.replyQuestions !== "string" || note.replyQuestions.length > NOTE_LIMITS.question))) {
        throw new TypeError("A venue note has an unsupported status, field type or length.");
      }
      const hasReply = Boolean(note.reply.trim());
      const questionText = note.question ?? suggestedQuestions(item.pick, row.date).join("\n");
      if (hasReply !== (note.replyQuestions !== null)
          || (hasReply && note.replyQuestions !== questionText && note.status === "reply_recorded")) {
        throw new TypeError("A venue note has an inconsistent reply and question history.");
      }
      return Object.freeze({ key: row.key, date: row.date, note: Object.freeze({ ...note }) });
    }));
  }

  function replaceRecords(rows) {
    const prepared = prepareRecords(rows);
    const replacement = new Map(prepared.map(({ key, date, note }) => [JSON.stringify([key, date]), note]));
    records = replacement;
  }

  return Object.freeze({ entries, setField, text, sourceLabel, snapshotRecords, prepareRecords, replaceRecords });
}

/** Own only this section; the existing app owns plan acceptance and retirement. */
export function mountVenueFollowup(root, current, onChange = () => {}) {
  const list = root.querySelector("[data-contact-list]");
  const summary = root.querySelector("[data-contact-summary]");
  const status = root.querySelector("[data-contact-status]");
  const source = root.querySelector("[data-contact-source]");
  const download = root.querySelector("[data-contact-download]");
  let session = null;
  const noteFiles = mountVenueNoteFiles(root, () => ({
    state: currentState(), origin: current().origin, model: session,
  }), sync, CONTACT_STATES);

  function currentState() {
    const { state, date } = current();
    if (!session || !state) throw new Error("Generate a plan before preparing venue notes.");
    if (setWeek(state, date).weekStart !== state.weekStart) {
      throw new Error("Choose a date in the displayed week before using venue notes.");
    }
    return state;
  }

  function updateSummary(state) {
    const entries = session.entries(state);
    const count = (value) => entries.filter((entry) => entry.note.status === value).length;
    summary.textContent = `${entries.length} scheduled visits · ${count("not_contacted")} not contacted · ${count("awaiting_reply")} awaiting reply · ${count("reply_recorded")} replies recorded · ${count("follow_up")} need follow-up.`;
  }

  function notePrint({ note, questionsChangedAfterReply }) {
    return `<dl class="contact-print-note">
      <dt>Caregiver contact status</dt><dd data-contact-print="status">${esc(CONTACT_STATES[note.status])}</dd>
      <dt data-contact-reply-label>${questionsChangedAfterReply ? "Earlier reply / notes (for the previous questions)" : "Venue reply / your notes"}</dt><dd data-contact-print="reply">${esc(note.reply || "No reply details entered.")}</dd>
      <dt>Next step</dt><dd data-contact-print="nextStep">${esc(note.nextStep || "No next step recorded.")}</dd>
    </dl>`;
  }

  function sync() {
    noteFiles.changed();
    onChange();
    if (!session) return;
    root.hidden = false;
    download.disabled = true;
    status.textContent = "";
    try {
      const state = currentState();
      const visits = session.entries(state);
      source.textContent = session.sourceLabel;
      list.hidden = false;
      list.innerHTML = visits.map((entry) => {
        const { key, date, day, pick, occurrence, questions, questionsChangedAfterReply, note } = entry;
        return `<li class="contact-visit" data-contact-key="${esc(key)}" data-contact-date="${esc(date)}">
        <h4>${esc(pick.name)} <span>${esc(day)} <time datetime="${date}">${date}</time></span></h4>
        <p class="why mono">Suggested visit ${occurrence} · Qloo id: ${esc(pick.entity_id)}</p>
        <p class="why contact-explanation">Original plan explanation (heuristic): ${esc(pick.why)}</p>
        <h5>Questions to ask</h5><ul class="contact-questions">${questions.length ? questions.map((question) => `<li>${esc(question)}</li>`).join("") : "<li>No questions entered.</li>"}</ul>
        <details class="contact-edit contact-question-editor">
          <summary>Edit questions for this visit</summary>
          <label>Questions for ${esc(pick.name)} on ${date}
            <textarea data-contact-field="question" rows="5" maxlength="${NOTE_LIMITS.question}"></textarea>
          </label>
        </details>
        <div class="contact-earlier-questions" data-contact-earlier${questionsChangedAfterReply ? "" : " hidden"}>
          <p>Questions changed after these notes were entered. Review the earlier notes before following up on the revised questions.</p>
          <h5>Questions for the earlier reply / notes</h5><p data-contact-reply-questions>${esc(note.replyQuestions)}</p>
        </div>
        <div class="contact-edit">
          <label>Contact status for ${esc(pick.name)} on ${date}
            <select data-contact-field="status">${Object.entries(CONTACT_STATES).map(([value, label]) => `<option value="${value}"${value === note.status ? " selected" : ""}>${label}</option>`).join("")}</select>
          </label>
          <label>Venue reply / your notes for ${esc(pick.name)} on ${date}
            <textarea data-contact-field="reply" rows="3" maxlength="${NOTE_LIMITS.reply}" placeholder="Record what the venue said and anything still unclear."></textarea>
          </label>
          <label>Next step for ${esc(pick.name)} on ${date}
            <textarea data-contact-field="nextStep" rows="2" maxlength="${NOTE_LIMITS.nextStep}" placeholder="For example: ask about the entrance before deciding to go."></textarea>
          </label>
        </div>${notePrint(entry)}
      </li>`;
      }).join("");
      // Set values after parsing: HTML strips a leading LF inside <textarea>.
      visits.forEach((entry, index) => {
        const visit = list.children[index];
        visit.querySelector('[data-contact-field="question"]').value = entry.questionText;
        visit.querySelector('[data-contact-field="reply"]').value = entry.note.reply;
        visit.querySelector('[data-contact-field="nextStep"]').value = entry.note.nextStep;
      });
      updateSummary(state);
      root.dataset.empty = String(visits.length === 0);
      download.disabled = visits.length === 0;
      if (!visits.length) status.textContent = "Schedule a suggested pick to prepare questions and venue notes.";
    } catch (error) {
      list.hidden = true;
      summary.textContent = "";
      status.textContent = `Venue worksheet unavailable: ${error.message}`;
    }
  }

  function edit(event) {
    const input = event.target.closest("[data-contact-field]");
    if (!input || !root.contains(input)) return;
    // Commit each native control once; the paired event must not erase a refusal.
    if (event.type !== (input.dataset.contactField === "status" ? "change" : "input")) return;
    const visit = input.closest("[data-contact-key]");
    noteFiles.changed();
    onChange();
    try {
      const state = currentState();
      const note = session.setField(state, visit.dataset.contactKey, visit.dataset.contactDate, input.dataset.contactField, input.value);
      const entry = session.entries(state).find((item) => item.key === visit.dataset.contactKey);
      visit.querySelector('[data-contact-field="status"]').value = note.status;
      visit.querySelector(".contact-questions").innerHTML = entry.questions.length
        ? entry.questions.map((question) => `<li>${esc(question)}</li>`).join("") : "<li>No questions entered.</li>";
      visit.querySelector("[data-contact-earlier]").hidden = !entry.questionsChangedAfterReply;
      visit.querySelector("[data-contact-reply-questions]").textContent = note.replyQuestions || "";
      visit.querySelector("[data-contact-reply-label]").textContent = entry.questionsChangedAfterReply
        ? "Earlier reply / notes (for the previous questions)" : "Venue reply / your notes";
      for (const output of visit.querySelectorAll("[data-contact-print]")) {
        const field = output.dataset.contactPrint;
        output.textContent = field === "status" ? CONTACT_STATES[note.status]
          : note[field] || (field === "reply" ? "No reply details entered." : "No next step recorded.");
      }
      updateSummary(state);
      status.textContent = "Your note is available for this visit in this tab. Save venue notes to edit them later, or print/download a readable call sheet.";
      noteFiles.refresh();
    } catch (error) {
      if (input.dataset.contactField === "status" && session) {
        try {
          const entry = session.entries(currentState()).find((item) => item.key === visit.dataset.contactKey && item.date === visit.dataset.contactDate);
          if (entry) input.value = entry.note.status;
        } catch { /* A retired or moved visit cannot accept this edit. */ }
      }
      status.textContent = `Note not updated: ${error.message}`;
    }
  }

  root.addEventListener("input", edit);
  root.addEventListener("change", edit);
  download.addEventListener("click", () => {
    let url, link;
    try {
      const state = currentState();
      const content = session.text(state);
      url = URL.createObjectURL(new Blob([content], { type: "text/plain;charset=utf-8" }));
      link = document.createElement("a");
      link.href = url;
      link.download = `tastetable-venue-contacts-${state.weekStart}.txt`;
      document.body.append(link);
      link.click();
      status.textContent = "Call sheet prepared. This copy contains your notes and the visit dates shown; later edits do not update it.";
    } catch (error) {
      try {
        download.disabled = session.entries(currentState()).length === 0;
      } catch {
        download.disabled = true;
      }
      status.textContent = `Call sheet unavailable: ${error.message}`;
    } finally {
      link?.remove();
      if (url) setTimeout(() => URL.revokeObjectURL(url), 1000);
    }
  });

  return Object.freeze({
    accept(state, savedSource = "") { noteFiles.retire(); session = createVenueFollowup(state, savedSource); sync(); },
    snapshot() {
      const state = currentState();
      const origin = current().origin;
      if (!origin) throw new Error("Open or generate a plan before saving a caregiver handoff.");
      session.entries(state);
      return { state, origin, model: session };
    },
    acceptPrepared(state, model) {
      model.entries(state);
      noteFiles.retire();
      session = model;
      sync();
    },
    sync,
    retire() {
      session = null;
      noteFiles.retire();
      root.hidden = true;
      list.replaceChildren();
      summary.textContent = source.textContent = status.textContent = "";
      download.disabled = true;
      onChange();
    },
  });
}

/** Explicit companion files for an existing accepted plan's editable venue notes. */
import { makeWeekFile } from "./week_file.mjs";

export const VENUE_NOTE_FORMAT = "tastetable.venue-notes.v1";
export const VENUE_NOTE_BYTE_LIMIT = 2 * 1024 * 1024;
export const VENUE_NOTE_RECORD_LIMIT = 256;
const object = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
const exact = (value, names) => object(value) && Object.keys(value).length === names.length
  && names.every((name) => Object.hasOwn(value, name));
const bytes = (text) => new TextEncoder().encode(text).byteLength;
function requireValue(condition, message) { if (!condition) throw new TypeError(message); }

function canonical(value, depth = 0) {
  requireValue(depth <= 64, "The notes file contains unsupported nesting.");
  if (Array.isArray(value)) return "[" + value.map((entry) => canonical(entry, depth + 1)).join(",") + "]";
  if (object(value)) return "{" + Object.keys(value).sort().map((key) =>
    JSON.stringify(key) + ":" + canonical(value[key], depth + 1)).join(",") + "}";
  requireValue(value === null || typeof value === "string" || typeof value === "boolean"
    || (typeof value === "number" && Number.isFinite(value)), "The notes file contains a value that is not finite JSON data.");
  return JSON.stringify(value);
}

function planOrigin({ origin, state, model }) {
  model.entries(state); // Retain the original model\'s accepted-plan identity guard.
  // Reuse the maintained complete response/input and immutable week admission.
  const saved = JSON.parse(makeWeekFile({ ...origin, state }).text);
  return { receivedAt: saved.receivedAt, calendarId: saved.calendarId, inputs: saved.inputs, response: saved.response };
}

function readEnvelope(value, context) {
  requireValue(exact(value, ["format", "savedAt", "origin", "records"]) && value.format === VENUE_NOTE_FORMAT,
    "Choose a TasteTable venue-notes file in the supported v1 format.");
  requireValue(typeof value.savedAt === "string" && Number.isFinite(new Date(value.savedAt).getTime())
    && new Date(value.savedAt).toISOString() === value.savedAt, "The notes file has an invalid saved timestamp.");
  requireValue(exact(value.origin, ["receivedAt", "calendarId", "inputs", "response"])
    && canonical(value.origin) === canonical(planOrigin(context)),
  "These notes belong to a different accepted plan. Open the original saved week first.");
  requireValue(Array.isArray(value.records) && value.records.length <= VENUE_NOTE_RECORD_LIMIT,
    "A notes file can contain at most 256 visit/date records.");
  return Object.freeze({ savedAt: value.savedAt, records: context.model.prepareRecords(value.records) });
}

export function makeVenueNoteFile(context, now = new Date()) {
  const envelope = { format: VENUE_NOTE_FORMAT, savedAt: now.toISOString(),
    origin: planOrigin(context), records: context.model.snapshotRecords() };
  readEnvelope(envelope, context);
  const text = JSON.stringify(envelope, null, 2) + "\n";
  requireValue(bytes(text) <= VENUE_NOTE_BYTE_LIMIT, "The complete notes file exceeds 2 MiB. Current notes are unchanged.");
  return { filename: `tastetable-venue-notes-${context.state.weekStart}.json`, text };
}

export function readVenueNoteFile(text, context) {
  requireValue(typeof text === "string" && bytes(text) <= VENUE_NOTE_BYTE_LIMIT,
    "Choose a venue-notes JSON file no larger than 2 MiB.");
  let envelope;
  try { envelope = JSON.parse(text.replace(/^\uFEFF/, "")); }
  catch { throw new TypeError("The venue-notes file is not valid JSON."); }
  return readEnvelope(envelope, context);
}

/** Own only file controls. The existing worksheet owns note rendering and edits. */
export function mountVenueNoteFiles(root, current, render, states) {
  const save = root.querySelector("[data-contact-file-save]");
  const open = root.querySelector("[data-contact-file-open]");
  const input = root.querySelector("[data-contact-file-input]");
  const preview = root.querySelector("[data-contact-file-preview]");
  const description = root.querySelector("[data-contact-file-description]");
  const list = root.querySelector("[data-contact-file-records]");
  const apply = root.querySelector("[data-contact-file-apply]");
  const cancel = root.querySelector("[data-contact-file-cancel]");
  const status = root.querySelector("[data-contact-file-status]");
  const source = root.querySelector("[data-contact-file-source]");
  let revision = 0, pending = null;

  function discard(message = "") {
    revision += 1;
    pending = null;
    preview.hidden = true;
    list.replaceChildren();
    description.textContent = "";
    apply.disabled = true;
    status.textContent = message;
  }
  function refresh() {
    let available = false;
    try { planOrigin(current()); available = true; } catch { /* The app controls plan/date admission. */ }
    save.disabled = open.disabled = !available;
  }
  function changed() {
    discard(pending ? "The plan or venue notes changed. Open the notes file again to review a new replacement." : "");
    refresh();
  }
  function contextStillCurrent(saved) {
    const next = current();
    requireValue(saved.revision === revision && next.model === saved.context.model
      && next.state === saved.context.state && next.origin === saved.context.origin,
    "The plan or venue notes changed. Open the notes file again.");
    return next;
  }
  function showFile(file, result, context, token) {
    const currentVisits = new Set(context.model.entries(context.state).map(({ key, date }) => JSON.stringify([key, date])));
    const visible = result.records.filter(({ key, date }) => currentVisits.has(JSON.stringify([key, date]))).length;
    description.textContent = `“${file.name}” — saved ${result.savedAt}. ${result.records.length} recorded visit/date notes; ${visible} match visits currently scheduled, ${result.records.length - visible} are for other dates or omitted visits. Replace all ${context.model.snapshotRecords().length} current records with this file? The plan and its arrangement stay as they are.`;
    for (const record of result.records) {
      const pick = context.state.picks.find(({ key }) => key === record.key);
      const item = document.createElement("li"), title = document.createElement("h5"), text = document.createElement("pre");
      title.textContent = `${record.date} — suggested visit ${context.state.picks.indexOf(pick) + 1}: ${pick.pick.name}`;
      text.textContent = [
        `Contact status: ${states[record.note.status]}`,
        "Questions: " + (record.note.question ?? "(Original suggested questions for this visit/date.)"),
        "Reply / notes: " + (record.note.reply || "(No reply details entered.)"),
        ...(record.note.replyQuestions !== null ? ["Questions associated with that reply: " + record.note.replyQuestions] : []),
        "Next step: " + (record.note.nextStep || "(No next step recorded.)"),
      ].join("\n");
      item.append(title, text); list.append(item);
    }
    pending = { revision: token, context, result, filename: file.name };
    preview.hidden = false;
    apply.disabled = false;
    status.textContent = result.records.length ? "File checked. Review the records before replacing your notes."
      : "This file has no note records. Replace will clear your current notes.";
  }

  save.addEventListener("click", () => {
    let url, link;
    try {
      const output = makeVenueNoteFile(current());
      url = URL.createObjectURL(new Blob([output.text], { type: "application/json;charset=utf-8" }));
      link = document.createElement("a");
      link.href = url; link.download = output.filename;
      document.body.append(link); link.click();
      status.textContent = "Venue notes prepared. Keep this file with the matching saved week to resume editing later.";
    } catch (error) { status.textContent = "Venue notes could not be saved: " + error.message; }
    finally { link?.remove(); if (url) setTimeout(() => URL.revokeObjectURL(url), 1000); refresh(); }
  });
  open.addEventListener("click", () => {
    discard(); input.value = "";
    try { planOrigin(current()); input.click(); }
    catch (error) { status.textContent = "Venue notes unavailable: " + error.message; }
  });
  input.addEventListener("change", async () => {
    const file = input.files?.[0]; input.value = ""; discard();
    if (!file) return;
    const token = revision;
    let context;
    try {
      context = current();
      const captured = { revision: token, context };
      requireValue(file.size <= VENUE_NOTE_BYTE_LIMIT, "Choose a venue-notes file no larger than 2 MiB.");
      status.textContent = "Reading the selected notes file…";
      const buffer = await file.arrayBuffer();
      if (token !== revision) return;
      contextStillCurrent(captured);
      requireValue(buffer.byteLength <= VENUE_NOTE_BYTE_LIMIT, "Choose a venue-notes file no larger than 2 MiB.");
      let text;
      try { text = new TextDecoder("utf-8", { fatal: true }).decode(buffer); }
      catch { throw new TypeError("The venue-notes file must contain valid UTF-8 text."); }
      const result = readVenueNoteFile(text, context);
      contextStillCurrent(captured);
      showFile(file, result, context, token);
    } catch (error) {
      if (token === revision) { discard("Venue notes not opened: " + error.message); refresh(); }
    }
  });
  input.addEventListener("cancel", () => discard("No notes file chosen. Current notes are unchanged."));
  cancel.addEventListener("click", () => discard("Replacement cancelled. Current notes are unchanged."));
  apply.addEventListener("click", () => {
    if (!pending) return;
    const saved = pending;
    try {
      const context = contextStillCurrent(saved);
      context.model.replaceRecords(saved.result.records);
      discard();
      render();
      source.textContent = `Venue notes reopened from “${saved.filename}” (saved ${saved.result.savedAt}). These remain editable caregiver records; source checks have not been run again.`;
      source.hidden = false;
      status.textContent = "Venue notes replaced. Plan, dates and original checks are unchanged.";
    } catch (error) { discard("Venue notes not replaced: " + error.message); refresh(); }
  });
  return Object.freeze({ changed, refresh, retire() {
    discard(); input.value = ""; source.textContent = ""; source.hidden = true;
    save.disabled = open.disabled = true;
  } });
}

/** One explicit local file for an arranged week and its source-bound venue notes. */
import { makeWeekFile, readWeekFile } from "./week_file.mjs";
import { makeVenueNoteFile, readVenueNoteFile } from "./venue_note_file.mjs";
import { CONTACT_STATES, createVenueFollowup } from "./venue_followup.mjs";
import { offWeekPicks, weekRows } from "./week_plan.mjs";

export const CAREGIVER_HANDOFF_FORMAT = "tastetable.caregiver-handoff.v1";
export const CAREGIVER_HANDOFF_BYTE_LIMIT = 6 * 1024 * 1024;
const bytes = (text) => new TextEncoder().encode(text).byteLength;
const exact = (value, names) => value !== null && typeof value === "object" && !Array.isArray(value)
  && Object.keys(value).length === names.length && names.every((name) => Object.hasOwn(value, name));
const json = (value) => JSON.stringify(value, null, 2) + "\n";
function requireValue(condition, message) { if (!condition) throw new TypeError(message); }

/** Both native sections and their full source binding are admitted in isolation. */
export function readCaregiverHandoff(text) {
  requireValue(typeof text === "string" && bytes(text) <= CAREGIVER_HANDOFF_BYTE_LIMIT,
    "Choose a caregiver handoff JSON file no larger than 6 MiB.");
  let envelope;
  try { envelope = JSON.parse(text.replace(/^\uFEFF/, "")); }
  catch { throw new TypeError("The caregiver handoff file is not valid JSON."); }
  requireValue(exact(envelope, ["format", "savedAt", "week", "venueNotes"])
    && envelope.format === CAREGIVER_HANDOFF_FORMAT,
  "Choose a TasteTable caregiver-handoff file in the supported v1 format.");
  requireValue(typeof envelope.savedAt === "string" && Number.isFinite(new Date(envelope.savedAt).getTime())
    && new Date(envelope.savedAt).toISOString() === envelope.savedAt,
  "The caregiver handoff has an invalid saved timestamp.");
  const opened = readWeekFile(json(envelope.week));
  const origin = { response: opened.response, inputs: opened.inputs,
    receivedAt: opened.receivedAt, calendarId: opened.calendarId };
  const savedSource = `Saved caregiver handoff (saved ${envelope.savedAt}). Source labels and checks are retained from the file; they have not been run again.`;
  const model = createVenueFollowup(opened.state, savedSource);
  const notes = readVenueNoteFile(json(envelope.venueNotes), { origin, state: opened.state, model });
  model.replaceRecords(notes.records);
  return Object.freeze({ ...opened, origin, model, records: notes.records,
    handoffSavedAt: envelope.savedAt, notesSavedAt: notes.savedAt });
}

export function makeCaregiverHandoff(context, now = new Date()) {
  const envelope = { format: CAREGIVER_HANDOFF_FORMAT, savedAt: now.toISOString(),
    week: JSON.parse(makeWeekFile({ ...context.origin, state: context.state }, now).text),
    venueNotes: JSON.parse(makeVenueNoteFile(context, now).text) };
  const text = json(envelope);
  readCaregiverHandoff(text);
  return { filename: `tastetable-caregiver-handoff-${context.state.weekStart}.json`, text };
}

/** File preparation is read-only. Only the explicit, still-current Apply calls accept. */
export function mountCaregiverHandoff(root, { current, prepare, accept }) {
  const save = root.querySelector("[data-handoff-save]");
  const open = root.querySelector("[data-handoff-open]");
  const input = root.querySelector("[data-handoff-input]");
  const preview = root.querySelector("[data-handoff-preview]");
  const description = root.querySelector("[data-handoff-description]");
  const source = root.querySelector("[data-handoff-source]");
  const visits = root.querySelector("[data-handoff-visits]");
  const records = root.querySelector("[data-handoff-records]");
  const apply = root.querySelector("[data-handoff-apply]");
  const cancel = root.querySelector("[data-handoff-cancel]");
  const status = root.querySelector("[data-handoff-status]");
  let revision = 0, pending = null, reading = false;

  function discard(message = "") {
    revision += 1;
    pending = null;
    reading = false;
    cancel.hidden = true;
    preview.hidden = true;
    apply.disabled = true;
    description.textContent = source.textContent = "";
    visits.replaceChildren();
    records.replaceChildren();
    status.textContent = message;
  }
  function refresh() {
    try { const context = current(); context.model.entries(context.state); save.disabled = false; }
    catch { save.disabled = true; }
  }
  function changed() {
    const wasPending = reading || pending !== null || !preview.hidden;
    discard(wasPending ? "The week, inputs or notes changed. Open the handoff again to review it against your current work." : "");
    refresh();
  }
